import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';

function AnimatedNumber({ value, color }) {
  const [display, setDisplay] = useState(value);

  useEffect(() => {
    setDisplay(value);
  }, [value]);

  return (
    <div style={{
      fontSize:   20,
      fontWeight: 700,
      color,
      lineHeight: 1.1,
      transition: 'color .3s'
    }}>
      {display}
    </div>
  );
}

export default function StatsRow() {
  const { stats, wsConnected } = useApp();

  const items = [
    {
      icon:     '📷',
      label:    'Cameras',
      value:    `${stats.cameras_online || 0} / ${stats.cameras_total || 0}`,
      sub:      'Online',
      subColor: '#3b82f6'
    },
    {
      icon:     '🔍',
      label:    'Total Detections',
      value:    stats.total_detections || 0,
      sub:      'Today',
      subColor: '#64748b'
    },
    {
      icon:     '🚨',
      label:    'Active Alerts',
      value:    stats.active_alerts || 0,
      sub:      'View All',
      subColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#64748b',
      valColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#22c55e'
    },
    {
      icon:     '💚',
      label:    'System Status',
      value:    wsConnected ? 'Healthy' : 'Offline',
      sub:      wsConnected ? 'All Systems Operational' : 'Reconnecting...',
      subColor: '#64748b',
      valColor: wsConnected ? '#22c55e' : '#f97316',
      fontSize: 16
    },
  ];

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: 'repeat(4,1fr)',
      borderBottom:        '1px solid #1e2d47',
      flexShrink:          0,
      gap:                 '1px',
      background:          '#1e2d47'
    }}>
      {items.map((s, i) => (
        <div key={i} style={{
          background: '#111827',
          padding:    '10px 14px',
          display:    'flex',
          alignItems: 'center',
          gap:        12
        }}>
          <span style={{ fontSize: 24 }}>{s.icon}</span>
          <div>
            <div style={{ fontSize: 10, color: '#64748b' }}>{s.label}</div>
            <AnimatedNumber
              value={s.value}
              color={s.valColor || '#fff'}
            />
            <div style={{ fontSize: 10, color: s.subColor, marginTop: 2 }}>
              {s.sub}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
